window.AUTH=window.AUTH||{};window.AUTH["24-1056"]={"d":"24-1056","id":"2025/24-1056","n":"Rico v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Isabel Rico","date":"2025-08-14","url":"https://www.supremecourt.gov/DocketPDF/24/24-1056/369734/20250814143948147_24-1056%20Rico%20TS%20Br.%208.14.25%20pdfA.pdf","side":"pet","n":96},{"k":"respondent","label":"Brief of respondent United States","date":"2025-09-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-1056/374687/20250915154205683_24-1056%20--%20Rico%20v.%20U.S.%20with%20appendix.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioner Isabel Rico","date":"2025-10-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-1056/379723/20251015151306443_24-1056%20Rico%20Reply%20Br.%2010.15.25%20pdfA.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us2r23_4g15.pdf","tr":true,"items":[{"t":"case","label":"Anderson v. Corall","cite":"263 U.S. 193","y":1923,"id":"scdb/1923-028","sc":1,"op":4,"ar":1,"sum":"1. Mere lapse of time, without imprisonment or other restraint contemplated by law, does not constitute service of sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23-25","1":"4, 14, 26, 27, 30, 33","2":"19"}},{"t":"case","label":"Artis v. District of Columbia","cite":"583 U.S. 71","y":2018,"id":"2017/16-460","sc":1,"op":1,"sum":"The Court decided that the tolling provision of 28 U.S.C. § 1367 suspends or “stops the clock” on the limitations period for supplemental state law claims while the underlying case is pending in federal court and for 30 days thereafter, rather than merely providing a 30-day grace period after dismissal for the plaintiff to refile in state court.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Beck v. Prupis","cite":"529 U.S. 494","y":2000,"id":"1999/98-1480","sc":1,"op":1,"sum":"The Court held that an injury caused by an overt act that is not an act of racketeering or otherwise wrongful under the Racketeer Influenced and Corrupt Organizations Act does not give rise to a cause of action under RICO. Thus, because Prupis' scheme to remove Beck from SIG was not an act of racketeering itself, Beck had no ground to sue him under RICO.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"22","1":"39"}},{"t":"case","label":"Bradley v. United States","cite":"410 U.S. 605","y":1973,"id":"1972/71-1304","sc":1,"sum":"On May 6, 1971, petitioners were convicted and sentenced for narcotics offenses committed in March 1971. They received the minimum five-year sentences under a provision that was mandatory and made the sentences not subject to suspension, probation, or parole. Effective May 1, 1971, that provision was repealed and liberalized by the Comprehensive Drug Abuse Prevention and Control Act of 1970. On petitioners' motion …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"Caballery v. United States Parole Commission","cite":"673 F.2d 43","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/673/43/","by":{"0":"38-39","1":"28, 33","2":"20"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"0":"34-35","1":"34"}},{"t":"case","label":"City & County of San Francisco v. EPA","cite":"145 S. Ct. 704","y":2025,"id":"2024/23-753","sc":1,"sum":"The challenged end-result permitting provisions—which make the permittee responsible for the quality of the water in the body of water into which the permittee discharges pollutants—exceed the Environmental Protection Agency’s authority under the Clean Water Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21"}},{"t":"case","label":"Commissioner v. Acker","cite":"361 U.S. 87","y":1959,"id":"1959/13","sc":1,"sum":"Under the Internal Revenue Code of 1939, the failure of.a taxpayer, without reasonable cause, to file a declaration of estimated income tax, as required by § 58, subjects him to the addition to the tax prescribed by § 294 (d) (1) (A) for failure to file the declaration;. but it does not subject him also to the addition to the tax prescribed by § 294 (d) (2) for the filing of a \"substantial underestimate\" of his tax. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"ar":2,"sum":"A district court considering whether to revoke a defendant’s term of supervised release may not consider 18 U. S. C. §3553(a)(2)(A), which covers retribution vis-à-vis the defendant’s underlying criminal offense.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 19, 42-43","1":"5, 30"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"sum":"An affirmative act of inducement by a public official, such as a demand, is not an element of the offense of extortion \"under color of official right\" prohibited by the Hobbs Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Gozlon-Peretz v. United States","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"sum":"Supervised release applies for all drug offenses in the categories specified by ADAA § 1002 that were committed after the ADAA was enacted but before November 1, 1987.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"45"}},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"sum":"The Court, in a 5-to-4 decision, held that since the Eighth Amendment does not contain a proportionality guarantee, the determination of whether a punishment is \"cruel and unusual\" is not made with reference to the particular offense. Moreover, the Cruel and Unusual Punishment Clause protects against unusual methods of punishment, not necessarily cruel ones.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Henrique v. United States Marshal","cite":"476 F. Supp. 618","y":1979,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./476/618/","by":{"0":"39"}},{"t":"case","label":"Holguin-Hernandez v. United States","cite":"589 U.S. 169","y":2020,"id":"2019/18-7739","sc":1,"sum":"The Court held that a criminal defendant's district-court argument for a specific sentence preserved his claim on appeal that the sentence imposed was unreasonably long.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Isbrandtsen Co. v. Johnson","cite":"343 U.S. 779","y":1952,"id":"scdb/1951-093","sc":1,"sum":"In an admiralty proceeding by a seaman against his employer to recover wages earned on a merchant vessel of United States registry, the employer may not set off against the seaman's wages its expenditures for the medical care and hospitalization of another member of the crew necessitated by injuries unjustifiably inflicted on him by the seaman during the voyage on which the wages were earned.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"op":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"0":"4","1":"3, 7, 12, 16, 17, 32, 36, 45"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Kousisis v. United States","cite":"145 S. Ct. 1382","y":2025,"id":"2024/23-909","sc":1,"sum":"A defendant who induces a victim to enter into a transaction under materially false pretenses may be convicted of federal fraud even if the defendant did not seek to cause the victim economic loss.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"578 U.S. 189","y":2016,"id":"2015/14-8913","sc":1,"sum":"The Court held that an error in the application of the U.S. Sentencing Guidelines that results in the wrong Guideline range affected the defendant’s substantial rights.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Mont v. United States","cite":"587 U.S. 514","y":2019,"id":"2018/17-8995","sc":1,"op":3,"sum":"Pretrial detention later credited as time served for a new conviction tolls a supervised-release term under 18 U. S. C. §3624(e), even if the court must make the tolling calculation after learning whether the time will be credited.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22, 26","1":"7, 13, 17, 18, 23, 29, 31, 38, 39, 47","2":"8"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"op":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Nicholas v. United States","cite":"527 F.2d 1160","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/527/1160/","sum":"Noting “allegations that [the defendant] had failed to file his monthly supervision reports after July 31, 1971, * * * and that he had failed to keep the Department advised of his whereabouts”.","sumSrc":"brief:1","by":{"0":"40-41","1":"28, 34","2":"21"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Tennessee v. Davis","cite":"100 U.S. 257","y":1880,"id":"scdb/1879-096","sc":1,"sum":"1. Sect. 613 of the Kevised Statutes of the United States, which declares that “ when any civil suit or criminal prosecution is commenced in any court of a State against any officer appointed under or acting by authority of any revenue law of the United States now or hereafter enacted, or against any person acting under or by authority of any such officer, on account of any act done under color of his office or of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Bailey","cite":"444 U.S. 394","y":1980,"id":"1979/78-990","sc":1,"sum":"Upon being apprehended after their escape from the District of Columbia jail, respondents were indicted for violating 18 U. S. C. § 751 (a), which governs escape from federal custody. At the trial of respondents Cooley, Bailey, and Walker, the District Court, after respondents had adduced evidence of conditions in the jail and their reasons for not returning to custody, rejected their proffered jury instruction on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"United States v. Barinas","cite":"865 F.3d 99","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/865/99/","by":{"0":"44"}},{"t":"case","label":"United States v. Buchanan","cite":"638 F.3d 448","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/638/448/","op":1,"by":{"0":"6, 44","1":"7, 46"}},{"t":"case","label":"United States v. Cartagena-Lopez","cite":"979 F.3d 356","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/979/356/","by":{"0":"44"}},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47"}},{"t":"case","label":"United States v. Fisher","cite":"895 F.2d 208","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/895/208/","op":1,"by":{"0":"40"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"0":"42-43"}},{"t":"case","label":"United States v. Gulley","cite":"130 F.4th 1178","y":2025,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/130/1178/","by":{"0":"22"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"United States v. Haymond","cite":"588 U.S. 634","y":2019,"id":"2018/17-1672","sc":1,"sum":"The Tenth Circuit’s judgment—that 18 U. S. C. §3583(k)’s last two sentences are unconstitutional and unenforceable—is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"United States v. Hernández-Ferrer","cite":"599 F.3d 63","y":2010,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/599/63/","op":1,"by":{"0":"46"}},{"t":"case","label":"United States v. Island","cite":"916 F.3d 249","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/916/249/","sum":"Describing the “difficulties associated with defining a ‘fugitive’ in the supervised release context”.","sumSrc":"brief:0","by":{"0":"47-48, 50","1":"18"}},{"t":"case","label":"United States v. Janvier","cite":"599 F.3d 264","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/599/264/","ar":1,"by":{"0":"6, 21","1":"39"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"op":2,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"0":"4, 20, 42-43, 50","1":"3, 12, 13, 16-18, 37, 45, 48","2":"8, 10"}},{"t":"case","label":"United States v. Lancer","cite":"508 F.2d 719","y":1975,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/508/719/","by":{"0":"40","1":"29","2":"21"}},{"t":"case","label":"United States v. Murguia-Oliveros","cite":"421 F.3d 951","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/421/951/","by":{"0":"48"}},{"t":"case","label":"United States v. Quality Stores, Inc.","cite":"572 U.S. 141","y":2014,"id":"2013/12-1408","sc":1,"sum":"The Court found that severance payments made to employees who were unwillingly laid off are taxable under the Federal Insurance Contributions Act.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Swick","cite":"137 F.4th 336","y":2025,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/137/336/","ar":4,"by":{"0":"31, 33, 40, 48-49","1":"15, 44, 46, 47"}},{"t":"case","label":"x United States v. Talley","cite":"83 F.4th 1296","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/83/1296/","op":1,"by":{"0":"16-17, 24, 26, 41-42, 45-46"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":2003,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","2":"18"}},{"t":"case","label":"United States v. Turley","cite":"352 U.S. 407","y":1957,"id":"1956/289","sc":1,"sum":"In the National Motor Vehicle Theft Act, 18 U. S. C. § 2312, which makes it a federal crime to transport in interstate or foreign commerce a motor vehicle \"knowing the same to have been stolen,\" the word \"stolen\" is not limited to takings which amount to common-law larceny, but it includes all takings of motor vehicles with a criminal intent to deprive the owner of the rights and benefits of ownership.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35"}},{"t":"case","label":"Yegiazaryan v. Smagin","cite":"599 U.S. 533","y":2023,"id":"2022/22-381","sc":1,"sum":"A plaintiff alleges a “domestic injury” as required by RJR Nabisco, Inc. v. European Community, 579 U. S. 325, for filing a private civil suit under the Racketeer Influenced and Corrupt Organizations Act, 18 U. S. C. §1964(c), when the circumstances surrounding the injury indicate it arose in the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Zerbst v. Kidwell","cite":"304 U.S. 359","y":1938,"id":"scdb/1937-051","sc":1,"ar":1,"sum":"A prisoner sentenced to a federal penal institution for an offense committed while he was on parole from such an institution may be required by the Parole Board to serve the unexpired portiou of his first sentence after the expiration of his second sentence. P. 363. 92 F. 2d 756, reversed. Together with No. 783, Zerbst, Warden, v. Smith; No. 784, Same v. Collins; No. 785, Same v. Owens; No. 786, Same v. Peel; No. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"27, 32","2":"19"}},{"t":"usc","label":"18 U.S.C. § 3290","url":"https://www.law.cornell.edu/uscode/text/18/3290","stext":{"head":"§3290. Fugitives from justice","paras":[[0,"No statute of limitations shall extend to any person fleeing from justice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3290?type=usc&year=mostrecent&link-type=html"},"head":"§3290. Fugitives from justice","tname":"Crimes and Criminal Procedure","by":{"0":"23","2":"13"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","stext":{"head":"§3551. Authorized sentences","paras":[[0,"(a) In General.—Except as otherwise specifically provided, a defendant who has been found guilty of an offense described in any Federal statute, including sections 13 and 1153 of this title, other than an Act of Congress applicable exclusively in the District of Columbia or the Uniform Code of Military Justice, shall be sentenced in accordance with the provisions of this chapter so as to achieve the purposes set forth in subparagraphs (A) through (D) of section 3553(a)(2) to the extent that they are applicable in light of all the circumstances of the case."],[0,"(b) Individuals.—An individual found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B;"],[1,"(2) a fine as authorized by subchapter C; or"],[1,"(3) a term of imprisonment as authorized by subchapter D."],[0,"A sentence to pay a fine may be imposed in addition to any other sentence. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."],[0,"(c) Organizations.—An organization found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B; or"],[1,"(2) a fine as authorized by subchapter C."],[0,"A sentence to pay a fine may be imposed in addition to a sentence to probation. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3551?type=usc&year=mostrecent&link-type=html"},"head":"§3551. Authorized sentences","tname":"Crimes and Criminal Procedure","by":{"0":"30","1":"3"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"46, 46"}},{"t":"usc","label":"18 U.S.C. § 3561","url":"https://www.law.cornell.edu/uscode/text/18/3561","subs":["(a)"],"by":{"0":"32"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","by":{"0":"32"}},{"t":"usc","label":"18 U.S.C. § 3565","url":"https://www.law.cornell.edu/uscode/text/18/3565","subs":["(c)"],"by":{"0":"41"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(b)","(b)(1)","(b)(2)","(b)(3)","(c)","(d)","(e)","(e)(1)","(e)(2)","(e)(3)","(g)","(h)","(i)","(j)","(k)","(a)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"3, 5, 19, 19, 19, 19, 5, 42, 5, 16, 22-23, 42, 45, 5, 5, 45, 5, 11, 16, 18, 26, 45, 17, 6, 19, 6-7, 21-22, 32, 41, 46, 49, 5, 5","1":"21, 21, 21, 21, 21, 21, 21, 21, 21, 21, 21","2":"11-13, 12, 1, 11-12, 4, 12, 10, 15, 24"}},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(e)"],"stext":{"head":"§3624. Release of a prisoner","paras":[[0,"(a) Date of Release.—A prisoner shall be released by the Bureau of Prisons on the date of the expiration of the prisoner's term of imprisonment, less any time credited toward the service of the prisoner's sentence as provided in subsection (b). If the date for a prisoner's release falls on a Saturday, a Sunday, or a legal holiday at the place of confinement, the prisoner may be released by the Bureau on the last preceding weekday."],[0,"(b) Credit Toward Service of Sentence for Satisfactory Behavior.—(1) Subject to paragraph (2), a prisoner who is serving a term of imprisonment of more than 1 year 1 other than a term of imprisonment for the duration of the prisoner's life, may receive credit toward the service of the prisoner's sentence of up to 54 days for each year of the prisoner's sentence imposed by the court, subject to determination by the Bureau of Prisons that, during that year, the prisoner has displayed exemplary compliance with institutional disciplinary regulations. Subject to paragraph (2), if the Bureau determines that, during that year, the prisoner has not satisfactorily complied with such institutional regulations, the prisoner shall receive no such credit toward service of the prisoner's sentence or shall receive such lesser credit as the Bureau determines to be appropriate. In awarding credit under this section, the Bureau shall consider whether the prisoner, during the relevant period, has earned, or is making satisfactory progress toward earning, a high school diploma or an equivalent degree. Credit that has not been earned may not later be granted. Subject to paragraph (2), credit for the last year of a term of imprisonment shall be credited on the first day of the last year of the term of imprisonment."],[0,"(2) Notwithstanding any other law, credit awarded under this subsection after the date of enactment of the Prison Litigation Reform Act shall vest on the date the prisoner is released from custody."],[0,"(3) The Attorney General shall ensure that the Bureau of Prisons has in effect an optional General Educational Development program for inmates who have not earned a high school diploma or its equivalent."],[0,"(4) Exemptions to the General Educational Development requirement may be made as deemed appropriate by the Director of the Federal Bureau of Prisons."],[0,"(c) Prerelease Custody.—"],[1,"(1) In general.—The Director of the Bureau of Prisons shall, to the extent practicable, ensure that a prisoner serving a term of imprisonment spends a portion of the final months of that term (not to exceed 12 months), under conditions that will afford that prisoner a reasonable opportunity to adjust to and prepare for the reentry of that prisoner into the community. Such conditions may include a community correctional facility."],[1,"(2) Home confinement authority.—The authority under this subsection may be used to place a prisoner in home confinement for the shorter of 10 percent of the term of imprisonment of that prisoner or 6 months. The Bureau of Prisons shall, to the extent practicable, place prisoners with lower risk levels and lower needs on home confinement for the maximum amount of time permitted under this paragraph."],[1,"(3) Assistance.—The United States Probation System shall, to the extent practicable, offer assistance to a prisoner during prerelease custody under this subsection."],[1,"(4) No limitations.—Nothing in this subsection shall be construed to limit or restrict the authority of the Director of the Bureau of Prisons under section 3621."],[1,"(5) Reporting.—Not later than 1 year after the date of the enactment of the Second Chance Act of 2007 (and every year thereafter), the Director of the Bureau of Prisons shall transmit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report describing the Bureau's utilization of community corrections facilities. Each report under this paragraph shall set forth the number and percentage of Federal prisoners placed in community corrections facilities during the preceding year, the average length of such placements, trends in such utilization, the reasons some prisoners are not placed in community corrections facilities, and number of prisoners not being placed in community corrections facilities for each reason set forth, and any other information that may be useful to the committees in determining if the Bureau is utilizing community corrections facilities in an effective manner."],[1,"(6) Issuance of regulations.—The Director of the Bureau of Prisons shall issue regulations pursuant to this subsection not later than 90 days after the date of the enactment of the Second Chance Reauthorization Act of 2018, which shall ensure that placement in a community correctional facility by the Bureau of Prisons is—"],[2,"(A) conducted in a manner consistent with section 3621(b) of this title;"],[2,"(B) determined on an individual basis; and"],[2,"(C) of sufficient duration to provide the greatest likelihood of successful reintegration into the community."],[0,"(d) Allotment of Clothing, Funds, and Transportation.—Upon the release of a prisoner on the expiration of the prisoner's term of imprisonment, the Bureau of Prisons shall furnish the prisoner with—"],[1,"(1) suitable clothing;"],[1,"(2) an amount of money, not more than $500, determined by the Director to be consistent with the needs of the offender and the public interest, unless the Director determines that the financial position of the offender is such that no sum should be furnished; and"],[1,"(3) transportation to the place of the prisoner's conviction, to the prisoner's bona fide residence within the United States, or to such other place within the United States as may be authorized by the Director."],[0,"(e) Supervision After Release.—A prisoner whose sentence includes a term of supervised release after imprisonment shall be released by the Bureau of Prisons to the supervision of a probation officer who shall, during the term imposed, supervise the person released to the degree warranted by the conditions specified by the sentencing court. The term of supervised release commences on the day the person is released from imprisonment and runs concurrently with any Federal, State, or local term of probation or supervised release or parole for another offense to which the person is subject or becomes subject during the term of supervised release. A term of supervised release does not run during any period in which the person is imprisoned in connection with a conviction for a Federal, State, or local crime unless the imprisonment is for a period of less than 30 consecutive days. Upon the release of a prisoner by the Bureau of Prisons to supervised release, the Bureau of Prisons shall notify such prisoner, verbally and in writing, of the requirement that the prisoner adhere to an installment schedule, not to exceed 2 years except in special circumstances, to pay for any fine imposed for the offense committed by such prisoner, and of the consequences of failure to pay such fines under sections 3611 through 3614 of this title."],[0,"(f) Mandatory Functional Literacy Requirement.—"],[1,"(1) The Attorney General shall direct the Bureau of Prisons to have in effect a mandatory functional literacy program for all mentally capable inmates who are not functionally literate in each Federal correctional institution within 6 months from the date of the enactment of this Act."],[1,"(2) Each mandatory functional literacy program shall include a requirement that each inmate participate in such program for a mandatory period sufficient to provide the inmate with an adequate opportunity to achieve functional literacy, and appropriate incentives which lead to successful completion of such programs shall be developed and implemented."],[1,"(3) As used in this section, the term \"functional literacy\" means—"],[2,"(A) an eighth grade equivalence in reading and mathematics on a nationally recognized standardized test;"],[2,"(B) functional competency or literacy on a nationally recognized criterion-referenced test; or"],[2,"(C) a combination of subparagraphs (A) and (B)."],[1,"(4) Non-English speaking inmates shall be required to participate in an English-As-A-Second-Language program until they function at the equivalence of the eighth grade on a nationally recognized educational achievement test."],[1,"(5) The Chief Executive Officer of each institution shall have authority to grant waivers for good cause as determined and documented on an individual basis."],[0,"(g) Prerelease Custody or Supervised Release for Risk and Needs Assessment System Participants.—"],[1,"(1) Eligible prisoners.—This subsection applies in the case of a prisoner (as such term is defined in section 3635) who—"],[2,"(A) has earned time credits under the risk and needs assessment system developed under subchapter D (referred to in this subsection as the \"System\") in an amount that is equal to the remainder of the prisoner's imposed term of imprisonment;"],[2,"(B) has shown through the periodic risk reassessments a demonstrated recidivism risk reduction or has maintained a minimum or low recidivism risk, during the prisoner's term of imprisonment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3624?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§3624. Release of a prisoner","tname":"Crimes and Criminal Procedure","by":{"0":"3, 6, 20, 26, 32","1":"40-42","2":"6-9, 14, 19"}},{"t":"usc","label":"18 U.S.C. § 3653","url":"https://www.law.cornell.edu/uscode/text/18/3653","by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","by":{"0":"27"}},{"t":"usc","label":"18 U.S.C. § 4210","url":"https://www.law.cornell.edu/uscode/text/18/4210","subs":["(b)","(b)(2)","(c)","(c)(1976)"],"tname":"Crimes and Criminal Procedure","by":{"0":"29, 37, 28, 31-32, 28-29, 31-32, 37, 41","1":"40-42","2":"15, 13-14, 13-15"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 118-83","url":"https://www.govinfo.gov/link/plaw/118/public/83","by":{"0":"30"}},{"t":"law","label":"xii Parole Commission and Reorganization Act, Pub. L. No. 94-233","url":"https://www.govinfo.gov/link/statute/90/219","by":{"0":"28"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"4, 32"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1796","by":{"0":"7","1":"41"}},{"t":"reg","label":"28 C.F.R. § 2.10","url":"https://www.ecfr.gov/current/title-28/section-2.10","subs":["(c)"],"by":{"0":"38"}},{"t":"reg","label":"28 C.F.R. § 2.40","url":"https://www.ecfr.gov/current/title-28/section-2.40","subs":["(e)"],"by":{"0":"30","2":"16"}},{"t":"reg","label":"28 C.F.R. § 2.52","url":"https://www.ecfr.gov/current/title-28/section-2.52","subs":["(c)","(c)(1)"],"by":{"0":"28, 30"}},{"t":"reg","label":"Paroling, Recommitting and Supervising Federal Prisoners, 41 Fed. Reg. 19,326","url":"https://www.govinfo.gov/link/fr/41/19326","by":{"0":"28"}},{"t":"reg","label":"Paroling, Recommitting, and Supervising Federal Prisoners, 48 Fed. Reg. 22,917","url":"https://www.govinfo.gov/link/fr/48/22917","by":{"0":"28-29, 37","1":"42","2":"13"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Barrier v. Beaver","cite":"712 F.2d 231","y":1983,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/712/231/","by":{"1":"41"}},{"t":"case","label":"Biddle v. Asher","cite":"295 F. 670","y":1924,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./295/670/","by":{"1":"27","2":"19"}},{"t":"case","label":"Black v. Romano","cite":"471 U.S. 606","y":1985,"id":"1984/84-465","sc":1,"sum":"Respondent, upon pleading guilty in a Missouri state court to controlled substance offenses, was put on probation and given suspended prison sentences. Two months later, he was arrested for and subsequently charged with leaving the scene of an automobile accident, a felony. After a hearing, the judge who had sentenced respondent, finding that respondent had violated his probation conditions by committing a felony, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Dimmick v. Tompkins","cite":"194 U.S. 540","y":1904,"id":"scdb/1903-089","sc":1,"sum":"An appeal directly to this court from the Circuit Court denying a writ of habeas corpus is proper where the petition contains averments that the imprisonment is in violation of the Federal Constitution.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26","2":"20"}},{"t":"case","label":"Drinkall v. Spiegel","cite":"36 A. 830","y":1896,"court":"Conn.","url":"https://www.courtlistener.com/c/A./36/830/","by":{"1":"27","2":"20"}},{"t":"case","label":"Edmonds v. Compagnie Generale Transatlantique","cite":"443 U.S. 256","y":1979,"id":"1978/78-479","sc":1,"sum":"Petitioner longshoreman, while employed by a stevedoring concern that respondent shipowner -had engaged to unload cargo from its vessel, was injured in the course of that work, and received benefits for the injury from his employer under the Longshoremen's and Harbor Workers' Compensation Act (Act). Petitioner also brought this negligence action against respondent in Federal District Court, wherein the jury …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Federal Bureau of Investigation v. Fazaga","cite":"595 U.S. 344","y":2022,"id":"2021/20-828","sc":1,"sum":"Section 1806(f) of the Foreign Intelligence Surveillance Act of 1978—providing a procedure under which a trial-level court or other authority may consider the legality of electronic surveillance conducted under FISA and order specified forms of relief—does not displace the state secrets privilege.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Glus v. Brooklyn E. Dist. Terminal","cite":"359 U.S. 231","y":1959,"id":"1958/446","sc":1,"sum":"If petitioner can prove that respondent's responsible agents conducted themselves in such a way that he was justifiably misled into a good-faith belief that he could begin his action at any time within seven years after it accrued, he is entitled to have his case tried on the merits, and the District Court erred in dismissing the case on the ground that it was barred by the three-year limitation. Pp. 231-235. 253 F. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 14, 44, 47"}},{"t":"case","label":"Hollon v. Hopkins","cite":"21 Kan. 638","y":1879,"url":"https://www.courtlistener.com/c/Kan./21/638/","by":{"1":"25, 26"}},{"t":"case","label":"Huddleston v. United States","cite":"415 U.S. 814","y":1974,"id":"1973/72-1076","sc":1,"sum":"Section 922 (a) (6) applies to the redemption of a firearm from a pawnshop.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Luckey v. State","cite":"14 Tex. 400","y":1855,"url":"https://www.courtlistener.com/c/Tex./14/400/","sum":"Finding that an escapee “was legally retaken, and must remain in custody until he is delivered in due course of law”.","sumSrc":"brief:1","by":{"1":"25"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Milhem v. United States","cite":"834 F.2d 118","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/834/118/","sum":"Rejecting bailee’s “claim that the issuance of the [abscondment-based] arrest warrant * * * ended his obligations under the bail-jumping statute”.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Moody v. Daggett","cite":"429 U.S. 78","y":1976,"id":"1976/74-6632","sc":1,"sum":"Petitioner federal parolee, imprisoned for federal crimes committed while on parole and clearly constituting parole violations, held not to be constitutionally entitled to an immediate parole revocation hearing, where a parole violator warrant was issued and lodged with the institution of his confinement as a \"detainer\" but was not executed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Nicolls v. Ingersoll","cite":"7 Johns. 145","y":1810,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Johns./7/145/","by":{"1":"25"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"sum":"The Court held that the law's plain language criminalized the smuggling scheme in this case. The common-law revenue rule did not bar the prosecution of the scheme, because no common-law case as of 1952 clearly established that the rule barred the U.S. from prosecuting a fraudulent scheme to evade foreign taxes.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Perttu v. Richards","cite":"605 U.S. 460","y":2025,"id":"2024/23-1324","sc":1,"sum":"Parties are entitled to a jury trial on the issue of exhaustion of remedies under The Prison Litigation Reform Act when that issue is intertwined with the merits of a claim that requires a jury trial under the Seventh Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"5, 14, 24, 29, 35"}},{"t":"case","label":"Schwamble v. Sheriff","cite":"22 Pa. 18","y":1853,"url":"https://www.courtlistener.com/c/Pa./22/18/","sum":"Finding that an escapee “was legally retaken, and must remain in custody until he is delivered in due course of law”.","sumSrc":"brief:1","by":{"1":"25"}},{"t":"case","label":"Shular v. United States","cite":"589 U.S. 154","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"United States v. Gerson","cite":"192 F. Supp. 864","y":1961,"court":"E.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./192/864/","sum":"Observing that “[t]he directives of the Act itself cannot be performed while [the probationer] is incarcerated”.","sumSrc":"brief:1","by":{"1":"31, 34","2":"19"}},{"t":"case","label":"United States v. Hamilton","cite":"986 F.3d 413","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/986/413/","by":{"1":"20"}},{"t":"case","label":"United States v. Ignacio Juarez","cite":"601 F.3d 885","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/601/885/","ar":1,"by":{"1":"15, 43, 47"}},{"t":"case","label":"United States v. Kebodeaux","cite":"570 U.S. 387","y":2013,"id":"2012/12-418","sc":1,"sum":"The Court held that the Necessary and Proper Clause gave Congress the power to create federal crimes and regulate their punishment, as well as apply the Sex Offender Registration and Notification Act (SORNA) on a defendant.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"United States v. Montenegro-Rojo","cite":"908 F.2d 425","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/908/425/","by":{"1":"6"}},{"t":"case","label":"United States v. Pisano","cite":"266 F. Supp. 913","y":1967,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./266/913/","by":{"1":"31"}},{"t":"case","label":"United States v. Ribota","cite":"792 F.3d 837","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/837/","sum":"Upholding contempt prosecution for post-abscondment violation of pretrial-release conditions.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"United States v. Thompson","cite":"924 F.3d 122","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/924/122/","by":{"1":"15, 43, 44, 47"}},{"t":"case","label":"United States v. Watson","cite":"633 F.3d 929","y":2011,"url":"https://www.courtlistener.com/c/F.3d/633/929/","by":{"1":"47"}},{"t":"case","label":"United States v. Workman","cite":"617 F.2d 48","y":1980,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/617/48/","by":{"1":"29","2":"21"}},{"t":"usc","label":"18 U.S.C. § 3161","url":"https://www.law.cornell.edu/uscode/text/18/3161","subs":["(h)(3)"],"by":{"1":"21, 21"}},{"t":"usc","label":"18 U.S.C. § 3148","url":"https://www.law.cornell.edu/uscode/text/18/3148","by":{"1":"21"}},{"t":"usc","label":"18 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/18/3601","stext":{"head":"§3601. Supervision of probation","paras":[[0,"A person who has been sentenced to probation pursuant to the provisions of subchapter B of chapter 227, or placed on probation pursuant to the provisions of chapter 403, or placed on supervised release pursuant to the provisions of section 3583, shall, during the term imposed, be supervised by a probation officer to the degree warranted by the conditions specified by the sentencing court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3601?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§3601. Supervision of probation","tname":"Crimes and Criminal Procedure","by":{"1":"40-42","2":"6-8, 24"}},{"t":"usc","label":"18 U.S.C. § 3603","url":"https://www.law.cornell.edu/uscode/text/18/3603","subs":["(1)","(2)","(3)"],"by":{"1":"40-42, 40-42, 40-42, 40-42"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(b)(1)(B)","(b)(1)(C)"],"by":{"1":"59, 59"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","by":{"1":"59"}},{"t":"case","label":"Anderson v. Alexander (In re Anderson)","cite":"230 P.2d 770","y":1951,"court":"Or.","url":"https://www.courtlistener.com/c/P.2d/230/770/","by":{"2":"19"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"sum":"To prevail under 42 U. S. C. §12112(a), a plaintiff must plead and prove that she held or desired a job, and could perform its essential functions with or without reasonable accommodation, at the time of an employer’s alleged act of disability-based discrimination; the judgment of the Eleventh Circuit is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"9"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"2":"17"}}]};